import{notFound}from"next/navigation";import{requireUser}from"@/lib/auth/guards";import{db}from"@/lib/db";import{artworkAction}from"@/app/actions";import{categoryLabel}from"@/lib/i18n";import{getLocale,getMessages}from"@/lib/i18n-server";export default async function Edit({params}:PageProps<"/dashboard/uploads/[id]/edit">){const u=await requireUser(),{id}=await params;const[a,cats,locale,m]=await Promise.all([db.artwork.findFirst({where:{id,authorId:u.id,status:{in:["DRAFT","REJECTED"]}}}),db.category.findMany(),getLocale(),getMessages()]);if(!a)notFound();return <section className="auth wide"><form action={artworkAction} className="panel"><h1>{m.editArtwork}</h1><input type="hidden" name="id" value={id}/><input type="hidden" name="op" value="update"/><input type="hidden" name="sourceLocale" value={locale}/><label>{m.title}<input name="title" defaultValue={a.title} required/></label><label>{m.description}<textarea name="description" defaultValue={a.description||""}/></label><label>{m.category}<select name="categoryId" defaultValue={a.categoryId||""}><option value="">{m.noCategory}</option>{cats.map(c=><option key={c.id} value={c.id}>{categoryLabel(c.slug,locale,c).name}</option>)}</select></label><button>{m.save}</button></form></section>}